/* v28.xx (cw-cx-reportnewsstyle): critic on the public recorder, 10-21: cap the raw preview, keep copy primary and use the shared text sizes. Copy and restore still use the original data. */
#root #settingsmodal.recmode #spane_rec{max-width:1320px;margin:0;width:100%;min-height:0;overflow:auto;box-sizing:border-box;padding:24px 0;align-self:flex-start;}
#root #settingsmodal.recmode #spane_rec > .msub{display:block !important;font-size:var(--fs-body);line-height:1.4;color:var(--tx-2);margin:0 0 16px;}
#root #settingsmodal.recmode #exporttext{flex:none !important;min-height:240px !important;height:240px;max-height:240px;box-sizing:border-box;padding:16px;font:400 16px/24px var(--f-body);color:var(--tx-2);border:1px solid var(--ui-line-hi);text-transform:lowercase;resize:none;}
#root #settingsmodal.recmode #exporttext + div{gap:16px !important;margin-top:16px !important;align-items:center;}
#root #settingsmodal.recmode #copybtn{height:48px;padding:0 24px !important;font-size:var(--fs-body);font-weight:600;background:var(--acc);color:var(--acc-ink);border-color:var(--acc);}
#root #settingsmodal.recmode #wipelog{height:48px;padding:0 24px !important;font-size:var(--fs-label);background:transparent;color:var(--tx-2);border-color:var(--ui-line-hi) !important;}
#root #settingsmodal.recmode #wipelog:hover,#root #settingsmodal.recmode #wipelog:focus-visible,#root #settingsmodal.recmode #wipelog.padfocus{color:var(--danger);border-color:var(--danger) !important;}
#root #settingsmodal.recmode #exporttext + div + div{margin-top:32px !important;padding-top:24px !important;padding-bottom:24px;}
#root #settingsmodal.recmode #exporttext + div + div > div:first-child{font-size:var(--fs-label) !important;line-height:24px;color:var(--tx-2) !important;letter-spacing:var(--track) !important;margin-bottom:8px;}
#root #settingsmodal.recmode #rescode{box-sizing:border-box;height:56px;min-height:56px;padding:12px 16px;border:1px solid var(--ui-line-hi);font-size:var(--fs-body);line-height:28px;}
#root #settingsmodal.recmode #rescode + div{margin-top:16px !important;gap:16px !important;}
#root #settingsmodal.recmode #resread{min-height:48px;padding:0 24px !important;font-size:var(--fs-label);}
#root #settingsmodal.recmode #settabs .invtab{font-size:var(--fs-label);min-height:48px;}
/* v28.xx (cw-cx-reportnewsstyle): the real pause news window uses 20px body notes and the existing near-full-screen modal, not the retired forced floor notice. */
#root #wnmodal{align-items:stretch !important;justify-content:flex-start !important;text-align:left !important;}
#root #wnmodal h3{font-size:var(--fs-title);}
#root #wnmodal #wnlist{max-width:none !important;width:100%;font-size:var(--fs-body) !important;line-height:1.6 !important;margin:24px 0 !important;}
#root #wnmodal #wnlist > div{padding:16px 0;margin:0 !important;border-bottom:1px solid var(--ui-line);}
#root #wnmodal #wnlist > div:last-child{border-bottom:0;}
</style><canvas id="cv"></canvas>

check:
{v:'VER',what:'public recorder has a bounded lowercase preview and primary copy action while preserving raw data, and pause news uses body size',
 run:function(){
   var ta=document.getElementById('exporttext'), oldValue, probe=null, bad=[];
   try{
     __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     openSettings('rec'); oldValue=ta.value; ta.value='REPORT Case Probe';
     var ts=getComputedStyle(ta), copy=document.getElementById('copybtn'), cs=getComputedStyle(copy), root=document.getElementById('root');
     if(ta.getBoundingClientRect().height>241) bad.push('raw preview exceeds 240px');
     if(parseFloat(ts.fontSize)<16||parseFloat(ts.lineHeight)<24||ts.textTransform!=='lowercase') bad.push('preview does not use readable lowercase text');
     if(ta.value!=='REPORT Case Probe') bad.push('display styling changed the raw report');
     probe=document.createElement('span'); probe.style.color='var(--acc)'; root.appendChild(probe);
     if(cs.backgroundColor!==getComputedStyle(probe).color||copy.getBoundingClientRect().height<48) bad.push('copy is not the primary 48px action');
     var res=document.getElementById('rescode'); if(res.getBoundingClientRect().height<56) bad.push('restore field is under 56px');
     wnOpen(); if(parseFloat(getComputedStyle(document.getElementById('wnlist')).fontSize)<20) bad.push('news notes are below 20px');
     return bad.length?bad.join('; '):null;
   } finally {
     if(ta&&oldValue!==undefined) ta.value=oldValue; if(probe) probe.remove();
     ['settingsmodal','wnmodal'].forEach(function(id){var el=document.getElementById(id);if(el)el.classList.remove('on');});
     try{__endRaid('abandon');}catch(_e){} __topClear();
   } }},
